ALTER TABLE "cohorts" ADD COLUMN "self_paced" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "courses" ADD COLUMN "format" text DEFAULT 'live' NOT NULL;--> statement-breakpoint
-- Boost Sales with AI becomes a recorded course (lib/self-paced.ts adds its self-paced intake on the next start).
UPDATE "courses" SET "format" = 'recorded', "completion_attendance_percent" = 100 WHERE "slug" = 'boost-sales-with-ai';--> statement-breakpoint
UPDATE "courses" SET "description" = 'A practical video course for business owners and sales teams, in six short lessons you watch whenever it suits you. Each lesson shows one way AI can bring in more sales; try it on your own business straight away and leave with something you can use the next morning. No technical background needed: if you can use WhatsApp, you can do this course.' WHERE "slug" = 'boost-sales-with-ai' AND "description" = 'A practical six-week live course for business owners and sales teams. Each week you learn one way AI can bring in more sales, try it on your own business during class, and leave with something you can use the next morning. No technical background needed: if you can use WhatsApp, you can do this course.';
